-- =====================================================================
-- SaludabementeERP - DDL manual para PostgreSQL / Neon
-- Ejecutar UNA sola vez (o sobre una base vacia) desde el SQL Editor de
-- Neon o con: psql "$DATABASE_URL" -f neon-schema-manual.sql
--
-- Notas:
--  * Los nombres de esquemas, tablas y columnas se escriben en minusculas
--    porque Hibernate/PostgreSQL pliegan los identificadores sin comillas.
--  * Las columnas IDENTITY usan BIGINT GENERATED BY DEFAULT AS IDENTITY.
--  * Los textos largos usan TEXT (no OID/LOB).
--  * Despues de ejecutar este script, configurar JPA_DDL_AUTO=validate.
-- =====================================================================

BEGIN;

CREATE SCHEMA IF NOT EXISTS slb_actividades;
CREATE SCHEMA IF NOT EXISTS slb_alertas;
CREATE SCHEMA IF NOT EXISTS slb_aptitud_fisica;
CREATE SCHEMA IF NOT EXISTS slb_asistencias;
CREATE SCHEMA IF NOT EXISTS slb_catalogo;
CREATE SCHEMA IF NOT EXISTS slb_metas;
CREATE SCHEMA IF NOT EXISTS slb_noticias;
CREATE SCHEMA IF NOT EXISTS slb_notificacion;
CREATE SCHEMA IF NOT EXISTS slb_nutricional;
CREATE SCHEMA IF NOT EXISTS slb_personal;
CREATE SCHEMA IF NOT EXISTS slb_recomendaciones_ia;
CREATE SCHEMA IF NOT EXISTS slb_seguridad;
CREATE SCHEMA IF NOT EXISTS slb_social;
CREATE SCHEMA IF NOT EXISTS sbl_team;
CREATE SCHEMA IF NOT EXISTS slb_teams;

-- =====================================================================
-- SLB_TEAM / equipos
-- =====================================================================

CREATE TABLE IF NOT EXISTS sbl_team.equipo (
    id_equipo            BIGINT GENERATED BY DEFAULT AS IDENTITY,
    nombre               VARCHAR(100) NOT NULL,
    descripcion          VARCHAR(255),
    imagen_key           VARCHAR(512),
    color                VARCHAR(7),
    slogan               VARCHAR(150),
    referencia_biblica   VARCHAR(100),
    texto_versiculo      VARCHAR(1000),
    id_usuario_lider     BIGINT,
    version              BIGINT NOT NULL,
    activo               BOOLEAN NOT NULL,
    CONSTRAINT pk_equipo PRIMARY KEY (id_equipo)
);

-- =====================================================================
-- SLB_CATALOGO
-- =====================================================================

CREATE TABLE IF NOT EXISTS slb_catalogo.cat_area_trabajo (
    id_area              BIGINT GENERATED BY DEFAULT AS IDENTITY,
    nombre               VARCHAR(100) NOT NULL,
    descripcion          VARCHAR(255),
    activo               BOOLEAN NOT NULL,
    fecha_creacion       TIMESTAMP(6) NOT NULL,
    usuario_creacion     VARCHAR(30) NOT NULL,
    fecha_modificacion   TIMESTAMP(6),
    usuario_modificacion VARCHAR(30),
    CONSTRAINT pk_cat_area_trabajo PRIMARY KEY (id_area),
    CONSTRAINT uq_cat_area_trabajo_nombre UNIQUE (nombre)
);

CREATE TABLE IF NOT EXISTS slb_catalogo.cat_periodo (
    id_periodo           BIGINT GENERATED BY DEFAULT AS IDENTITY,
    codigo               VARCHAR(10) NOT NULL,
    descripcion          VARCHAR(100) NOT NULL,
    fecha_inicio         DATE NOT NULL,
    fecha_fin            DATE NOT NULL,
    estado               VARCHAR(20) NOT NULL,
    cerrado_en           TIMESTAMP(6),
    cerrado_por          VARCHAR(50),
    fecha_creacion       TIMESTAMP(6) NOT NULL,
    usuario_creacion     VARCHAR(30) NOT NULL,
    fecha_modificacion   TIMESTAMP(6),
    usuario_modificacion VARCHAR(30),
    CONSTRAINT pk_cat_periodo PRIMARY KEY (id_periodo),
    CONSTRAINT uq_cat_periodo_codigo UNIQUE (codigo)
);

-- =====================================================================
-- SLB_PERSONAL
-- =====================================================================

CREATE TABLE IF NOT EXISTS slb_personal.persona (
    id_persona           BIGINT GENERATED BY DEFAULT AS IDENTITY,
    nombres              VARCHAR(100) NOT NULL,
    apellido_paterno     VARCHAR(100) NOT NULL,
    apellido_materno     VARCHAR(100),
    celular              VARCHAR(15),
    fecha_nacimiento     DATE NOT NULL,
    sexo                 VARCHAR(1) NOT NULL,
    email                VARCHAR(120),
    id_area              BIGINT,
    talla_polo           VARCHAR(5),
    estado_civil         VARCHAR(20),
    nivel_educativo      VARCHAR(30),
    id_equipo            BIGINT,
    activo               BOOLEAN NOT NULL,
    documento_identidad  VARCHAR(15) NOT NULL,
    avatar_url           VARCHAR(250),
    CONSTRAINT pk_persona PRIMARY KEY (id_persona),
    CONSTRAINT uq_persona_celular UNIQUE (celular),
    CONSTRAINT uq_persona_documento_identidad UNIQUE (documento_identidad),
    CONSTRAINT fk_persona_area_trabajo FOREIGN KEY (id_area)
        REFERENCES slb_catalogo.cat_area_trabajo (id_area),
    CONSTRAINT fk_persona_equipo FOREIGN KEY (id_equipo)
        REFERENCES sbl_team.equipo (id_equipo)
);

CREATE TABLE IF NOT EXISTS slb_personal.credencial_programa (
    id_credencial        BIGINT GENERATED BY DEFAULT AS IDENTITY,
    id_persona           BIGINT NOT NULL,
    codigo_qr_hash       VARCHAR(255) NOT NULL,
    fecha_emision        TIMESTAMP(6) NOT NULL,
    estado               VARCHAR(20) NOT NULL,
    CONSTRAINT pk_credencial_programa PRIMARY KEY (id_credencial),
    CONSTRAINT uq_credencial_programa_codigo_qr_hash UNIQUE (codigo_qr_hash),
    CONSTRAINT fk_credencial_programa_persona FOREIGN KEY (id_persona)
        REFERENCES slb_personal.persona (id_persona)
);

CREATE TABLE IF NOT EXISTS slb_personal.preferencia_comunicacion (
    id_preferencia            BIGINT GENERATED BY DEFAULT AS IDENTITY,
    id_persona                BIGINT NOT NULL,
    canal_preferido           VARCHAR(30),
    horario_contacto_inicio   TIME(6),
    horario_contacto_fin      TIME(6),
    acepta_recordatorios      BOOLEAN NOT NULL,
    CONSTRAINT pk_preferencia_comunicacion PRIMARY KEY (id_preferencia),
    CONSTRAINT uq_preferencia_comunicacion_persona UNIQUE (id_persona),
    CONSTRAINT fk_preferencia_comunicacion_persona FOREIGN KEY (id_persona)
        REFERENCES slb_personal.persona (id_persona)
);

-- =====================================================================
-- SLB_ACTIVIDADES
-- =====================================================================

CREATE TABLE IF NOT EXISTS slb_actividades.actividad (
    id_actividad                    BIGINT GENERATED BY DEFAULT AS IDENTITY,
    nombre                          VARCHAR(100) NOT NULL,
    descripcion                     VARCHAR(300),
    fecha_actividad                 DATE NOT NULL,
    hora_inicio                     TIME(6) NOT NULL,
    hora_fin                        TIME(6) NOT NULL,
    lugar                           VARCHAR(100) NOT NULL,
    estado                          VARCHAR(20) NOT NULL,
    id_usuario_creador              BIGINT NOT NULL,
    id_equipo_actividad             BIGINT,
    fecha_creacion                  TIMESTAMP(6),
    id_usuario_coordinador          BIGINT NOT NULL,
    puntaje_salud                   INTEGER,
    logo_key                        VARCHAR(255),
    logo_url                        VARCHAR(500),
    latitud_oficial                 NUMERIC(10,8),
    longitud_oficial                NUMERIC(11,8),
    tolerancia_geocerca_metros      INTEGER,
    requiere_check_in_out           BOOLEAN,
    duracion_minutos                INTEGER,
    periodo                         VARCHAR(10),
    permite_autoservicio            BOOLEAN,
    permite_escaneo_coordinador     BOOLEAN,
    cierre_asistencias_realizado    BOOLEAN,
    CONSTRAINT pk_actividad PRIMARY KEY (id_actividad)
);

CREATE TABLE IF NOT EXISTS slb_actividades.actividad_material (
    id_material          BIGINT GENERATED BY DEFAULT AS IDENTITY,
    id_actividad         BIGINT NOT NULL,
    descripcion          VARCHAR(200) NOT NULL,
    CONSTRAINT pk_actividad_material PRIMARY KEY (id_material)
);

CREATE TABLE IF NOT EXISTS slb_actividades.actividad_imagen (
    id_imagen            BIGINT GENERATED BY DEFAULT AS IDENTITY,
    id_actividad         BIGINT NOT NULL,
    imagen_key           VARCHAR(255) NOT NULL,
    imagen_url           VARCHAR(500) NOT NULL,
    descripcion          VARCHAR(200),
    orden                INTEGER,
    fecha_subida         TIMESTAMP(6) NOT NULL,
    CONSTRAINT pk_actividad_imagen PRIMARY KEY (id_imagen)
);

CREATE TABLE IF NOT EXISTS slb_actividades.actividad_inscrito (
    id_actividad         BIGINT NOT NULL,
    id_persona           BIGINT NOT NULL,
    fecha_inscripcion    TIMESTAMP(6) NOT NULL,
    inscrito_por_todos   BOOLEAN NOT NULL,
    CONSTRAINT pk_actividad_inscrito PRIMARY KEY (id_actividad, id_persona)
);

-- =====================================================================
-- SLB_ALERTAS
-- =====================================================================

CREATE TABLE IF NOT EXISTS slb_alertas.alerta_clinica (
    id                       BIGINT GENERATED BY DEFAULT AS IDENTITY,
    id_persona               BIGINT NOT NULL,
    id_evaluacion_origen     BIGINT NOT NULL,
    tipo_evaluacion_origen   VARCHAR(20) NOT NULL,
    puntaje_total            INTEGER NOT NULL,
    nivel_severidad          VARCHAR(15) NOT NULL,
    mensaje_resumen          VARCHAR(300),
    estado                   VARCHAR(15) NOT NULL,
    fecha_generacion         TIMESTAMP(6) NOT NULL,
    fecha_atencion           TIMESTAMP(6),
    id_usuario_atiende       BIGINT,
    observacion_atencion     VARCHAR(300),
    CONSTRAINT pk_alerta_clinica PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS slb_alertas.alerta_clinica_detalle (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY,
    id_alerta           BIGINT NOT NULL,
    tipo_indicador      VARCHAR(40) NOT NULL,
    valor_medido        NUMERIC(10,2) NOT NULL,
    valor_min           NUMERIC(10,2),
    valor_max           NUMERIC(10,2),
    clasificacion       VARCHAR(40) NOT NULL,
    puntos_riesgo       INTEGER NOT NULL,
    mensaje             VARCHAR(250),
    id_regla            BIGINT NOT NULL,
    entidad_regla       VARCHAR(60) NOT NULL,
    motor_detonante     VARCHAR(30) NOT NULL,
    CONSTRAINT pk_alerta_clinica_detalle PRIMARY KEY (id),
    CONSTRAINT fk_alerta_clinica_detalle_alerta FOREIGN KEY (id_alerta)
        REFERENCES slb_alertas.alerta_clinica (id)
);

CREATE TABLE IF NOT EXISTS slb_alertas.etiqueta_clinica (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY,
    codigo          VARCHAR(40) NOT NULL,
    nombre          VARCHAR(100) NOT NULL,
    descripcion     VARCHAR(300),
    color_hex       VARCHAR(7) NOT NULL,
    estado          VARCHAR(15) NOT NULL,
    fecha_baja      TIMESTAMP(6),
    CONSTRAINT pk_etiqueta_clinica PRIMARY KEY (id),
    CONSTRAINT uq_etiqueta_clinica_codigo UNIQUE (codigo)
);

CREATE INDEX IF NOT EXISTS idx_etiqueta_estado
    ON slb_alertas.etiqueta_clinica (estado);

CREATE TABLE IF NOT EXISTS slb_alertas.alerta_etiqueta (
    id                    BIGINT GENERATED BY DEFAULT AS IDENTITY,
    id_alerta             BIGINT NOT NULL,
    id_etiqueta           BIGINT NOT NULL,
    etiqueta_codigo       VARCHAR(40) NOT NULL,
    etiqueta_nombre       VARCHAR(100) NOT NULL,
    etiqueta_color_hex    VARCHAR(7) NOT NULL,
    asignada_por          VARCHAR(20) NOT NULL,
    fecha_asignacion      TIMESTAMP(6) NOT NULL,
    CONSTRAINT pk_alerta_etiqueta PRIMARY KEY (id),
    CONSTRAINT uq_alerta_etiqueta UNIQUE (id_alerta, id_etiqueta),
    CONSTRAINT fk_alerta_etiqueta_alerta FOREIGN KEY (id_alerta)
        REFERENCES slb_alertas.alerta_clinica (id)
);

CREATE INDEX IF NOT EXISTS idx_alerta_etiqueta_alerta
    ON slb_alertas.alerta_etiqueta (id_alerta);
CREATE INDEX IF NOT EXISTS idx_alerta_etiqueta_etiqueta
    ON slb_alertas.alerta_etiqueta (id_etiqueta);
CREATE INDEX IF NOT EXISTS idx_alerta_etiqueta_codigo
    ON slb_alertas.alerta_etiqueta (etiqueta_codigo);

CREATE TABLE IF NOT EXISTS slb_alertas.etiqueta_parametro (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY,
    id_etiqueta         BIGINT NOT NULL,
    id_parametro        BIGINT NOT NULL,
    parametro_codigo    VARCHAR(40) NOT NULL,
    parametro_nombre    VARCHAR(100) NOT NULL,
    parametro_unidad    VARCHAR(20),
    CONSTRAINT pk_etiqueta_parametro PRIMARY KEY (id),
    CONSTRAINT uq_etiqueta_parametro UNIQUE (id_etiqueta, id_parametro),
    CONSTRAINT fk_etiqueta_parametro_etiqueta FOREIGN KEY (id_etiqueta)
        REFERENCES slb_alertas.etiqueta_clinica (id)
);

CREATE INDEX IF NOT EXISTS idx_etiqueta_parametro_codigo
    ON slb_alertas.etiqueta_parametro (parametro_codigo);
CREATE INDEX IF NOT EXISTS idx_etiqueta_parametro_id
    ON slb_alertas.etiqueta_parametro (id_parametro);

CREATE TABLE IF NOT EXISTS slb_alertas.parametro_evaluacion (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY,
    codigo          VARCHAR(40) NOT NULL,
    nombre          VARCHAR(100) NOT NULL,
    unidad          VARCHAR(20),
    descripcion     VARCHAR(300),
    estado          VARCHAR(15) NOT NULL,
    fecha_baja      TIMESTAMP(6),
    CONSTRAINT pk_parametro_evaluacion PRIMARY KEY (id),
    CONSTRAINT uq_parametro_evaluacion_codigo UNIQUE (codigo)
);

CREATE INDEX IF NOT EXISTS idx_parametro_estado
    ON slb_alertas.parametro_evaluacion (estado);

CREATE TABLE IF NOT EXISTS slb_alertas.regla_abdominales (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY,
    sexo                VARCHAR(1) NOT NULL,
    edad_min            INTEGER NOT NULL,
    edad_max            INTEGER NOT NULL,
    repeticiones_min    INTEGER NOT NULL,
    repeticiones_max    INTEGER NOT NULL,
    direccion_riesgo    VARCHAR(15) NOT NULL,
    puntos_riesgo       INTEGER NOT NULL,
    clasificacion       VARCHAR(30) NOT NULL,
    estado              VARCHAR(15) NOT NULL,
    fecha_baja          TIMESTAMP(6),
    CONSTRAINT pk_regla_abdominales PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS slb_alertas.regla_carrera_400m (
    id                      BIGINT GENERATED BY DEFAULT AS IDENTITY,
    sexo                    VARCHAR(1) NOT NULL,
    edad_min                INTEGER NOT NULL,
    edad_max                INTEGER NOT NULL,
    tiempo_segundos_min     INTEGER NOT NULL,
    tiempo_segundos_max     INTEGER NOT NULL,
    direccion_riesgo        VARCHAR(15) NOT NULL,
    puntos_riesgo           INTEGER NOT NULL,
    clasificacion           VARCHAR(30) NOT NULL,
    estado                  VARCHAR(15) NOT NULL,
    fecha_baja              TIMESTAMP(6),
    CONSTRAINT pk_regla_carrera_400m PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS slb_alertas.regla_planchas (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY,
    sexo                VARCHAR(1) NOT NULL,
    edad_min            INTEGER NOT NULL,
    edad_max            INTEGER NOT NULL,
    repeticiones_min    INTEGER NOT NULL,
    repeticiones_max    INTEGER NOT NULL,
    direccion_riesgo    VARCHAR(15) NOT NULL,
    puntos_riesgo       INTEGER NOT NULL,
    clasificacion       VARCHAR(30) NOT NULL,
    estado              VARCHAR(15) NOT NULL,
    fecha_baja          TIMESTAMP(6),
    CONSTRAINT pk_regla_planchas PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS slb_alertas.regla_salta_soga (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY,
    sexo                VARCHAR(1) NOT NULL,
    edad_min            INTEGER NOT NULL,
    edad_max            INTEGER NOT NULL,
    saltos_min          INTEGER NOT NULL,
    saltos_max          INTEGER NOT NULL,
    direccion_riesgo    VARCHAR(15) NOT NULL,
    puntos_riesgo       INTEGER NOT NULL,
    clasificacion       VARCHAR(30) NOT NULL,
    estado              VARCHAR(15) NOT NULL,
    fecha_baja          TIMESTAMP(6),
    CONSTRAINT pk_regla_salta_soga PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS slb_alertas.regla_salto_sin_impulso (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY,
    sexo                VARCHAR(1) NOT NULL,
    edad_min            INTEGER NOT NULL,
    edad_max            INTEGER NOT NULL,
    distancia_cm_min    NUMERIC(5,2) NOT NULL,
    distancia_cm_max    NUMERIC(5,2) NOT NULL,
    direccion_riesgo    VARCHAR(15) NOT NULL,
    puntos_riesgo       INTEGER NOT NULL,
    clasificacion       VARCHAR(30) NOT NULL,
    estado              VARCHAR(15) NOT NULL,
    fecha_baja          TIMESTAMP(6),
    CONSTRAINT pk_regla_salto_sin_impulso PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS slb_alertas.regla_colesterol (
    id                      BIGINT GENERATED BY DEFAULT AS IDENTITY,
    sexo                    VARCHAR(1) NOT NULL,
    edad_min                INTEGER NOT NULL,
    edad_max                INTEGER NOT NULL,
    colesterol_mg_dl_min    NUMERIC(6,2) NOT NULL,
    colesterol_mg_dl_max    NUMERIC(6,2) NOT NULL,
    puntos_riesgo           INTEGER NOT NULL,
    clasificacion           VARCHAR(30) NOT NULL,
    estado                  VARCHAR(15) NOT NULL,
    fecha_baja              TIMESTAMP(6),
    CONSTRAINT pk_regla_colesterol PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS slb_alertas.regla_glucosa (
    id                      BIGINT GENERATED BY DEFAULT AS IDENTITY,
    sexo                    VARCHAR(1) NOT NULL,
    edad_min                INTEGER NOT NULL,
    edad_max                INTEGER NOT NULL,
    glucosa_mg_dl_min       NUMERIC(6,2) NOT NULL,
    glucosa_mg_dl_max       NUMERIC(6,2) NOT NULL,
    puntos_riesgo           INTEGER NOT NULL,
    clasificacion           VARCHAR(30) NOT NULL,
    estado                  VARCHAR(15) NOT NULL,
    fecha_baja              TIMESTAMP(6),
    CONSTRAINT pk_regla_glucosa PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS slb_alertas.regla_grasa_visceral (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY,
    sexo                VARCHAR(1) NOT NULL,
    edad_min            INTEGER NOT NULL,
    edad_max            INTEGER NOT NULL,
    nivel_min           NUMERIC(5,2) NOT NULL,
    nivel_max           NUMERIC(5,2) NOT NULL,
    puntos_riesgo       INTEGER NOT NULL,
    clasificacion       VARCHAR(30) NOT NULL,
    estado              VARCHAR(15) NOT NULL,
    fecha_baja          TIMESTAMP(6),
    CONSTRAINT pk_regla_grasa_visceral PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS slb_alertas.regla_imc (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY,
    sexo                VARCHAR(1) NOT NULL,
    edad_min            INTEGER NOT NULL,
    edad_max            INTEGER NOT NULL,
    imc_min             NUMERIC(5,2) NOT NULL,
    imc_max             NUMERIC(5,2) NOT NULL,
    puntos_riesgo       INTEGER NOT NULL,
    clasificacion       VARCHAR(30) NOT NULL,
    estado              VARCHAR(15) NOT NULL,
    fecha_baja          TIMESTAMP(6),
    CONSTRAINT pk_regla_imc PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS slb_alertas.regla_masa_muscular (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY,
    sexo                VARCHAR(1) NOT NULL,
    edad_min            INTEGER NOT NULL,
    edad_max            INTEGER NOT NULL,
    porcentaje_min      NUMERIC(5,2) NOT NULL,
    porcentaje_max      NUMERIC(5,2) NOT NULL,
    puntos_riesgo       INTEGER NOT NULL,
    clasificacion       VARCHAR(30) NOT NULL,
    estado              VARCHAR(15) NOT NULL,
    fecha_baja          TIMESTAMP(6),
    CONSTRAINT pk_regla_masa_muscular PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS slb_alertas.regla_perimetro_abdominal (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY,
    sexo                VARCHAR(1) NOT NULL,
    edad_min            INTEGER NOT NULL,
    edad_max            INTEGER NOT NULL,
    perimetro_cm_min    NUMERIC(5,2) NOT NULL,
    perimetro_cm_max    NUMERIC(5,2) NOT NULL,
    puntos_riesgo       INTEGER NOT NULL,
    clasificacion       VARCHAR(30) NOT NULL,
    estado              VARCHAR(15) NOT NULL,
    fecha_baja          TIMESTAMP(6),
    CONSTRAINT pk_regla_perimetro_abdominal PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS slb_alertas.regla_porcentaje_grasa (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY,
    sexo                VARCHAR(1) NOT NULL,
    edad_min            INTEGER NOT NULL,
    edad_max            INTEGER NOT NULL,
    porcentaje_min      NUMERIC(5,2) NOT NULL,
    porcentaje_max      NUMERIC(5,2) NOT NULL,
    puntos_riesgo       INTEGER NOT NULL,
    clasificacion       VARCHAR(30) NOT NULL,
    estado              VARCHAR(15) NOT NULL,
    fecha_baja          TIMESTAMP(6),
    CONSTRAINT pk_regla_porcentaje_grasa PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS slb_alertas.regla_presion_arterial (
    id                          BIGINT GENERATED BY DEFAULT AS IDENTITY,
    sexo                        VARCHAR(1) NOT NULL,
    edad_min                    INTEGER NOT NULL,
    edad_max                    INTEGER NOT NULL,
    sistolica_mm_hg_min         INTEGER NOT NULL,
    sistolica_mm_hg_max         INTEGER NOT NULL,
    diastolica_mm_hg_min        INTEGER NOT NULL,
    diastolica_mm_hg_max        INTEGER NOT NULL,
    puntos_riesgo               INTEGER NOT NULL,
    clasificacion               VARCHAR(30) NOT NULL,
    estado                      VARCHAR(15) NOT NULL,
    fecha_baja                  TIMESTAMP(6),
    CONSTRAINT pk_regla_presion_arterial PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS slb_alertas.regla_trigliceridos (
    id                          BIGINT GENERATED BY DEFAULT AS IDENTITY,
    sexo                        VARCHAR(1) NOT NULL,
    edad_min                    INTEGER NOT NULL,
    edad_max                    INTEGER NOT NULL,
    trigliceridos_mg_dl_min     NUMERIC(6,2) NOT NULL,
    trigliceridos_mg_dl_max     NUMERIC(6,2) NOT NULL,
    puntos_riesgo               INTEGER NOT NULL,
    clasificacion               VARCHAR(30) NOT NULL,
    estado                      VARCHAR(15) NOT NULL,
    fecha_baja                  TIMESTAMP(6),
    CONSTRAINT pk_regla_trigliceridos PRIMARY KEY (id)
);

CREATE TABLE IF NOT EXISTS slb_alertas.uso_card_alerta (
    id                      BIGINT GENERATED BY DEFAULT AS IDENTITY,
    id_usuario              BIGINT NOT NULL,
    ruta                    VARCHAR(160) NOT NULL,
    conteo                  INTEGER NOT NULL,
    fecha_actualizacion     TIMESTAMP(6) NOT NULL,
    CONSTRAINT pk_uso_card_alerta PRIMARY KEY (id),
    CONSTRAINT uk_uso_card_usuario_ruta UNIQUE (id_usuario, ruta)
);

-- =====================================================================
-- SLB_APTITUD_FISICA
-- =====================================================================

CREATE TABLE IF NOT EXISTS slb_aptitud_fisica.evaluacion (
    id_evaluacion                       BIGINT GENERATED BY DEFAULT AS IDENTITY,
    id_persona                          BIGINT NOT NULL,
    id_periodo                          BIGINT NOT NULL,
    documento_identidad_al_momento      VARCHAR(15) NOT NULL,
    nombres_completos_al_momento        VARCHAR(150) NOT NULL,
    edad_al_momento                     INTEGER NOT NULL,
    sexo_al_momento                     VARCHAR(1) NOT NULL,
    area_trabajo_al_momento             VARCHAR(100),
    fecha_evaluacion                    DATE NOT NULL,
    estado_evaluacion                   VARCHAR(30) NOT NULL,
    dictamen_global                     VARCHAR(50),
    observaciones_restricciones         VARCHAR(500),
    fitness_score                       NUMERIC(5,2),
    fecha_creacion                      TIMESTAMP(6) NOT NULL,
    usuario_creacion                    VARCHAR(30) NOT NULL,
    fecha_modificacion                  TIMESTAMP(6),
    usuario_modificacion                VARCHAR(30),
    CONSTRAINT pk_evaluacion PRIMARY KEY (id_evaluacion)
);

CREATE TABLE IF NOT EXISTS slb_aptitud_fisica.cardio (
    id_cardio                   BIGINT GENERATED BY DEFAULT AS IDENTITY,
    id_evaluacion               BIGINT NOT NULL,
    repeticiones_soga_30s       INTEGER NOT NULL,
    tiempo_carrera_400m_seg     INTEGER NOT NULL,
    dx_cardiovascular           VARCHAR(50) NOT NULL,
    fecha_creacion              TIMESTAMP(6) NOT NULL,
    usuario_creacion            VARCHAR(30) NOT NULL,
    fecha_modificacion          TIMESTAMP(6),
    usuario_modificacion        VARCHAR(30),
