    oculto_moderacion      BOOLEAN NOT NULL,
    CONSTRAINT pk_comentario PRIMARY KEY (id_comentario)
);

CREATE TABLE IF NOT EXISTS slb_social.comentario_adjunto (
    id_comentario_adjunto   BIGINT GENERATED BY DEFAULT AS IDENTITY,
    id_comentario           BIGINT NOT NULL,
