    orden                   INTEGER,
    mime                    VARCHAR(50),
    size_bytes              BIGINT,
    CONSTRAINT pk_comentario_adjunto PRIMARY KEY (id_comentario_adjunto)
);

CREATE TABLE IF NOT EXISTS slb_social.comentario_hashtag (
    id_comentario_hashtag   BIGINT GENERATED BY DEFAULT AS IDENTITY,
    id_comentario           BIGINT NOT NULL,
    tag                     VARCHAR(50) NOT NULL,
    CONSTRAINT pk_comentario_hashtag PRIMARY KEY (id_comentario_hashtag),
    CONSTRAINT uq_comentario_hashtag UNIQUE (id_comentario, tag)
);

CREATE TABLE IF NOT EXISTS slb_social.mencion (
    id_mencion          BIGINT GENERATED BY DEFAULT AS IDENTITY,
    tipo_contenido      VARCHAR(20) NOT NULL,
    id_contenido        BIGINT NOT NULL,
    tipo_mencion        VARCHAR(20) NOT NULL,
    ref_id              BIGINT NOT NULL,
    offset_inicio       INTEGER,
    offset_fin          INTEGER,
    CONSTRAINT pk_mencion PRIMARY KEY (id_mencion)
);

CREATE TABLE IF NOT EXISTS slb_social.post (
    id_post               BIGINT GENERATED BY DEFAULT AS IDENTITY,
    tipo_contenido        VARCHAR(20) NOT NULL,
    ref_id                BIGINT,
    origen_post_id        BIGINT,
    id_equipo_autor       BIGINT,
    titulo                VARCHAR(150),
    resumen               VARCHAR(500),
    lugar                 VARCHAR(150),
    fecha_evento          DATE,
    hora_inicio           VARCHAR(8),
    hora_fin              VARCHAR(8),
    ref_estado            VARCHAR(20),
    imagen_url            VARCHAR(500),
    coordinador_nombre    VARCHAR(200),
    autor_id              BIGINT NOT NULL,
    fecha_publicacion     TIMESTAMP(6) NOT NULL,
    fecha_actualizacion   TIMESTAMP(6),
    activo                BOOLEAN NOT NULL,
    oculto_moderacion     BOOLEAN NOT NULL,
    es_oficial            BOOLEAN NOT NULL,
    alcance_total         BIGINT NOT NULL,
    shares_total          BIGINT NOT NULL,
    sync_clave            VARCHAR(100),
    share_clave           VARCHAR(100),
    version               BIGINT NOT NULL,
    CONSTRAINT pk_post PRIMARY KEY (id_post),
    CONSTRAINT uk_post_tipo_ref UNIQUE (sync_clave),
    CONSTRAINT uk_post_autor_origen UNIQUE (share_clave),
    CONSTRAINT ck_post_tipo_contenido CHECK (
        ((tipo_contenido = 'ACTIVIDAD' OR tipo_contenido = 'NOTICIA')
            AND ref_id IS NOT NULL AND origen_post_id IS NULL)
        OR (tipo_contenido = 'MANUAL'
            AND ref_id IS NULL AND origen_post_id IS NULL)
        OR (tipo_contenido = 'SHARE'
            AND ref_id IS NULL AND origen_post_id IS NOT NULL)
    )
);

CREATE INDEX IF NOT EXISTS ix_post_muro
    ON slb_social.post (activo, fecha_publicacion DESC, id_post DESC);
CREATE INDEX IF NOT EXISTS ix_post_equipo
    ON slb_social.post (id_equipo_autor, activo, fecha_publicacion DESC);
CREATE INDEX IF NOT EXISTS ix_post_autor
    ON slb_social.post (autor_id, fecha_publicacion DESC);

CREATE TABLE IF NOT EXISTS slb_social.post_fijado (
    id_post_fijado        BIGINT GENERATED BY DEFAULT AS IDENTITY,
    id_post               BIGINT NOT NULL,
    scope_tipo            VARCHAR(20) NOT NULL,
    scope_id              BIGINT,
    fecha_fijado          TIMESTAMP(6) NOT NULL,
    id_usuario_fijador    BIGINT NOT NULL,
    fecha_expiracion      TIMESTAMP(6),
    CONSTRAINT pk_post_fijado PRIMARY KEY (id_post_fijado),
    CONSTRAINT uk_post_fijado UNIQUE (id_post, scope_tipo, scope_id),
    CONSTRAINT ck_post_fijado_scope CHECK (
        (scope_tipo = 'GLOBAL' AND scope_id IS NULL)
        OR ((scope_tipo = 'EQUIPO' OR scope_tipo = 'ACTIVIDAD')
            AND scope_id IS NOT NULL)
    )
);

CREATE TABLE IF NOT EXISTS slb_social.post_guardado (
    id_post           BIGINT NOT NULL,
    id_usuario        BIGINT NOT NULL,
    fecha_guardado    TIMESTAMP(6) NOT NULL,
    CONSTRAINT pk_post_guardado PRIMARY KEY (id_post, id_usuario)
);

CREATE TABLE IF NOT EXISTS slb_social.post_hashtag (
    id_post_hashtag   BIGINT GENERATED BY DEFAULT AS IDENTITY,
    id_post           BIGINT NOT NULL,
    tag               VARCHAR(50) NOT NULL,
    CONSTRAINT pk_post_hashtag PRIMARY KEY (id_post_hashtag),
    CONSTRAINT uq_post_hashtag UNIQUE (id_post, tag)
);

CREATE TABLE IF NOT EXISTS slb_social.post_imagen (
    id_post_imagen    BIGINT GENERATED BY DEFAULT AS IDENTITY,
    id_post           BIGINT NOT NULL,
    url               VARCHAR(500) NOT NULL,
    orden             INTEGER,
    CONSTRAINT pk_post_imagen PRIMARY KEY (id_post_imagen)
);

CREATE TABLE IF NOT EXISTS slb_social.post_vista (
    id_post_vista           BIGINT GENERATED BY DEFAULT AS IDENTITY,
    id_post                 BIGINT NOT NULL,
    id_usuario              BIGINT NOT NULL,
    fecha_primera_vista     TIMESTAMP(6) NOT NULL,
    fecha_ultima_vista      TIMESTAMP(6) NOT NULL,
    CONSTRAINT pk_post_vista PRIMARY KEY (id_post_vista),
    CONSTRAINT uk_post_vista UNIQUE (id_post, id_usuario)
);

CREATE TABLE IF NOT EXISTS slb_social.post_reporte (
    id_post_reporte         BIGINT GENERATED BY DEFAULT AS IDENTITY,
    reporte_clave           VARCHAR(100) NOT NULL,
    id_post                 BIGINT,
    id_comentario           BIGINT,
    id_usuario_reporta      BIGINT NOT NULL,
    motivo                  VARCHAR(20) NOT NULL,
    detalle                 VARCHAR(500),
    fecha_reporte           TIMESTAMP(6) NOT NULL,
    estado                  VARCHAR(20) NOT NULL,
    id_usuario_revisor      BIGINT,
    fecha_revision          TIMESTAMP(6),
    accion_tomada           VARCHAR(50),
    comentario_revision     VARCHAR(500),
    CONSTRAINT pk_post_reporte PRIMARY KEY (id_post_reporte),
    CONSTRAINT uk_reporte_unico UNIQUE (reporte_clave),
    CONSTRAINT ck_post_reporte_origen CHECK (
        (id_post IS NOT NULL AND id_comentario IS NULL)
        OR (id_post IS NULL AND id_comentario IS NOT NULL)
    )
);

CREATE INDEX IF NOT EXISTS ix_reporte_estado
    ON slb_social.post_reporte (estado, fecha_reporte);

CREATE TABLE IF NOT EXISTS slb_social.reaccion_comentario (
    id_comentario     BIGINT NOT NULL,
    id_usuario        BIGINT NOT NULL,
    tipo              VARCHAR(20) NOT NULL,
    fecha_reaccion    TIMESTAMP(6) NOT NULL,
    CONSTRAINT pk_reaccion_comentario PRIMARY KEY (id_comentario, id_usuario)
);

CREATE TABLE IF NOT EXISTS slb_social.reaccion_post (
    id_post           BIGINT NOT NULL,
    id_usuario        BIGINT NOT NULL,
    tipo              VARCHAR(20) NOT NULL,
    fecha_reaccion    TIMESTAMP(6) NOT NULL,
    CONSTRAINT pk_reaccion_post PRIMARY KEY (id_post, id_usuario)
);

COMMIT;
